# Keep only multi-cuisine restaurants\n","multi = df[df['Cuisines'].str.contains(',')].copy()\n","multi['Cuisine List'] = multi['Cuisines'].str.split(', ')\n","\n","# ── 1. Most Common Cuisine Pairs ──────────────────────────\n","combo_counter = Counter()\n","for cuisines in multi['Cuisine List']:\n","    for combo in combinations(sorted(cuisines), 2):\n","        combo_counter[combo] += 1\n","\n","top10_combos = combo_counter.most_common(10)\n","print(\"Top 10 Most Common Cuisine Combinations:\")\n","for combo, count in top10_combos:\n","    print(f\"  {' + '.join(combo)}: {count}\")\n","\n","# ── 2. Average Rating per Combination ─────────────────────\n","combo_ratings = {}\n","for _, row in multi.iterrows():\n","    rating = row['Aggregate rating']\n","    if rating == 0:\n","        continue\n","    for combo in combinations(sorted(row['Cuisine List']), 2):\n","        combo_ratings.setdefault(combo, []).append(rating)\n","\n","# Filter: minimum 30 restaurants per combo\n","combo_avg = {\n","    k: (sum(v) / len(v), len(v))\n","    for k, v in combo_ratings.items() if len(v) >= 30\n","}\n","top_rated = sorted(combo_avg.items(), key=lambda x: -x[1][0])[:10]\n","print(\"\\nTop 10 Highest-Rated Cuisine Combinations:\")\n","for combo, (avg, cnt) in top_rated:\n","    print(f\"  {' + '.join(combo)}: avg {avg:.2f} ({cnt} restaurants)\")\n","\n","# ── 3. Visualization ───────────────────────────────────────\n","labels_freq  = [' + '.join(c) for c, _ in top10_combos]\n","counts       = [n for _, n in top10_combos]\n","labels_rated = [' + '.join(c) for c, _ in top_rated]\n","avg_ratings  = [r for _, (r, _) in top_rated]\n","combo_counts = [n for _, (_, n) in top_rated]\n","\n","fig, axes = plt.subplots(2, 1, figsize=(12, 11))\n","fig.suptitle('Cuisine Combination Analysis', fontsize=15, fontweight='bold')\n","\n","# Chart 1 – Most Common\n","colors1 = plt.cm.Blues(np.linspace(0.4, 0.9, 10))[::-1]\n","bars1 = axes[0].barh(labels_freq[::-1], counts[::-1], color=colors1, edgecolor='white')\n","axes[0].set_title('Top 10 Most Common Cuisine Combinations', fontsize=12, fontweight='bold')\n","axes[0].set_xlabel('Number of Restaurants')\n","for bar, val in zip(bars1, counts[::-1]):\n","    axes[0].text(bar.get_width() + 10, bar.get_y() + bar.get_height()/2,\n","                 str(val), va='center', fontsize=9)\n","axes[0].set_xlim(0, max(counts) * 1.12)\n","\n","# Chart 2 – Highest Rated\n","colors2 = plt.cm.Greens(np.linspace(0.4, 0.9, 10))[::-1]\n","bars2 = axes[1].barh(labels_rated[::-1], avg_ratings[::-1], color=colors2, edgecolor='white')\n","axes[1].set_title('Top 10 Highest-Rated Combinations (min. 30 restaurants)',\n","                  fontsize=12, fontweight='bold')\n","axes[1].set_xlabel('Average Rating')\n","axes[1].set_xlim(3.7, 4.2)\n","for bar, val, cnt in zip(bars2, avg_ratings[::-1], combo_counts[::-1]):\n","    axes[1].text(bar.get_width() + 0.005, bar.get_y() + bar.get_height()/2,\n","                 f'{val:.2f}  (n={cnt})', va='center', fontsize=9)\n","\n","plt.tight_layout()\n","plt.savefig('cuisine_combinations.png', dpi=150, bbox_inches='tight')\n","plt.show()"]}]}